div.script:
var MIN_AMOUNT = ;

(function(){
    var items=[]; var total=0; var minAmt=parseFloat(MIN_AMOUNT);
    function render(){ var ul=document.getElementById('cartList'); ul.innerHTML=''; total=0; items.forEach(function(it,idx){ total+=it.price; var li=document.createElement('li'); li.className='flex justify-between'; li.innerHTML='<span>'+it.name+'</span><span>$'+it.price+'</span>'; ul.appendChild(li); }); document.getElementById('totalAmt').innerText=total; }
    document.querySelectorAll('.add-btn').forEach(function(b){ b.onclick=function(){ var card=b.parentElement; items.push({name:card.getAttribute('data-name'), price:parseFloat(card.getAttribute('data-price'))}); render(); }; });
    function toggleMode(){ var mode=(document.querySelector('input[name="sale_mode"]:checked')||{}).value||'takeout'; var dine=document.getElementById('dineInFields'); var del=document.getElementById('deliveryFields'); var com=document.getElementById('commercialFields'); var np=document.getElementById('nonprofitFields'); if(dine){ if(mode==='dine_in'){ dine.classList.remove('hidden'); } else { dine.classList.add('hidden'); } } if(del){ if(mode==='delivery_commercial' || mode==='delivery_nonprofit'){ del.classList.remove('hidden'); } else { del.classList.add('hidden'); } } if(com){ if(mode==='delivery_commercial'){ com.classList.remove('hidden'); } else { com.classList.add('hidden'); } } if(np){ if(mode==='delivery_nonprofit'){ np.classList.remove('hidden'); } else { np.classList.add('hidden'); } } }
    document.querySelectorAll('input[name="sale_mode"]').forEach(function(r){ r.addEventListener('change', toggleMode); });
    toggleMode();
    document.getElementById('checkoutBtn').onclick=function(){ if(items.length===0){ alert('請先加入品項'); return; } if(total<minAmt){ alert('未達最低消費：$'+minAmt); return; } var mode=(document.querySelector('input[name="sale_mode"]:checked')||{}).value||'takeout'; var payload={ items:items, total:total, customer_name:document.getElementById('custName').value||'', phone:document.getElementById('custPhone').value||'', sale_mode:mode };
        if(mode==='dine_in'){ payload.table_no=document.getElementById('tableNo').value||''; }
        if(mode==='delivery_commercial' || mode==='delivery_nonprofit'){ var addr=document.getElementById('deliveryAddress').value||''; if(!addr){ alert('請輸入外送地址'); return; } payload.address=addr; payload.schedule_time=document.getElementById('deliveryTime').value||''; payload.note=document.getElementById('deliveryNote').value||''; payload.delivery_fee=document.getElementById('deliveryFee').value||''; payload.tip_amount=document.getElementById('tipAmount').value||''; }
        if(mode==='delivery_commercial'){ payload.delivery_platform=document.getElementById('deliveryPlatform').value||''; }
        if(mode==='delivery_nonprofit'){ payload.nonprofit_program=document.getElementById('nonprofitProgram').value||''; }
        fetch('/api/order/create', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload)}).then(function(r){ return r.json(); }).then(function(d){ if(d.ok){ document.getElementById('orderRef').innerText='訂單已建立：'+d.order_ref; } else { alert('建立失敗：'+d.error); } }); };
})();
